function respond(array $p,int $s=200):never{http_response_code($s);echo json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function body():array{$d=json_decode(file_get_contents('php://input')?:'',true);return is_array($d)?$d:[];}
function read_json(string $f,array $default=[]):array{if(!is_file($f))return $default;$fp=fopen($f,'rb');if(!$fp)return $default;flock($fp,LOCK_SH);$raw=stream_get_contents($fp)?:'[]';flock($fp,LOCK_UN);fclose($fp);$d=json_decode($raw,true);return is_array($d)?$d:$default;}
function write_json(string $f,array $d):void{$tmp=$f.'.tmp';$fp=fopen($tmp,'wb');if(!$fp)throw new RuntimeException('write');flock($fp,LOCK_EX);fwrite($fp,json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));fflush($fp);flock($fp,LOCK_UN);fclose($fp);rename($tmp,$f);@chmod($f,0640);}
function clean(string $v,int $m=180):string{return mb_substr(trim(strip_tags($v)),0,$m);}
function uid():string{return bin2hex(random_bytes(12));}
function norm(string $v):string{$v=mb_strtolower(trim($v),'UTF-8');$v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$v)?:$v;return preg_replace('/[^a-z0-9]+/','',$v)?:'';}
function now():string{return gmdate(DATE_ATOM);}
function defaults_settings():array{return ['listing_duration_days'=>45,'max_seats'=>20,'recent_featured_count'=>2,'new_badge_hours'=>24,'price_compare_min'=>4,'mail_suspended'=>false,'site_texts'=>['hero_fr'=>'Trouvez facilement une place dans un abonnement partagé','hero_en'=>'Find a spot in a shared subscription','subtitle_fr'=>'Comparez les offres Spliiit, Sharesub et GoSplit au même endroit.','subtitle_en'=>'Compare Spliiit, Sharesub and GoSplit offers in one place.']];}
