function current_user():?array{return is_array($_SESSION['user']??null)?$_SESSION['user']:null;}
function require_auth():array{$u=current_user();if(!$u)respond(['error'=>'unauthorized'],401);return $u;}
function csrf(array $d):void{if(empty($_SESSION['csrf'])||!hash_equals((string)$_SESSION['csrf'],(string)($d['csrf']??'')))respond(['error'=>'csrf'],403);}
function can(string $permission):bool{$u=current_user();if(!$u)return false;if(in_array($u['role']??'', ['super','admin'],true))return true;return in_array($permission,$u['permissions']??[],true);}
function need(string $permission):array{$u=require_auth();if(!can($permission))respond(['error'=>'forbidden'],403);return $u;}
function log_action(string $action,array $details=[]):void{$u=current_user();$items=read_json(ACTIVITY_FILE);array_unshift($items,['id'=>uid(),'at'=>now(),'user'=>$u['username']??'système','role'=>$u['role']??'public','action'=>$action,'details'=>$details]);write_json(ACTIVITY_FILE,array_slice($items,0,1000));}
function site_url():string{$cfg=smtp_config();if(!empty($cfg['site_url']))return rtrim((string)$cfg['site_url'],'/');$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';$host=$_SERVER['HTTP_HOST']??'';return $host?(($https?'https':'http').'://'.$host):'';}
function manage_url(string $token):string{return site_url().'/#/mes-alertes?token='.rawurlencode($token);}
